diff.code:
resource "aws_cloudtrail" "main" {
  name                       = "org-trail"
  s3_bucket_name             = aws_s3_bucket.logs.id  # bucket in THIS workload account
  is_multi_region_trail      = false
  enable_log_file_validation = false
  # no event_selector block -> management events only
}

resource "aws_s3_bucket" "logs" {
  bucket = "acme-prod-cloudtrail-logs"
}

resource "aws_s3_bucket_versioning" "logs" {
  bucket = aws_s3_bucket.logs.id
  versioning_configuration { status = "Enabled" }
}

# no object lock, no separate account, no alarm on StopLogging/DeleteTrail
